    # Check if there exist k in {1, 2, 3} and distinct a1...ak+1 such that P(ak+1) = sum_{i=1}^k P(ai)
    # P(x) = -x^3 + c2*x^2 + c1*x + c0
    def P(x):
        return -x**3 + c2*x**2 + c1*x + c0

    # k = 1
    for a1 in range(-10, 11):
        for a2 in range(-10, 11):
            if a1 != a2 and P(a1) == P(a2):
                return True, 1, (a1, a2)
    # k = 2
    for a1 in range(-10, 11):
        for a2 in range(-10, 11):
            if a1 != a2:
                for a3 in range(-10, 11):
                    if a3 != a1 and a3 != a2 and P(a3) == P(a1) + P(a2):
                        return True, 2, (a1, a2, a3)
    # k = 3
    for a1 in range(-10, 11):
        for a2 in range(-10, 11):
            if a1 != a2:
                for a3 in range(-10, 11):
                    if a3 != a1 and a3 != a2:
                        for a4 in range(-10, 11):
                            if a4 != a1 and a4 != a2 and a4 != a3 and P(a4) == P(a1) + P(a2) + P(a3):
                                return True, 3, (a1, a2, a3, a4)
    return False, None, None

