def fast_test(d, c_coeffs, n, a_range):
    def P(x):
        res = -x**d
        for i, c in enumerate(reversed(c_coeffs)):
            res += c * (x**i)
        return res

    P_vals = {x: P(x) for x in a_range}
    val_to_xs = {}
    for x, val in P_vals.items():
        if val not in val_to_xs:
            val_to_xs[val] = []
        val_to_xs[val].append(x)

    # k = 1
    for val in val_to_xs:
        if len(val_to_xs[val]) >= 2:
            return True, 1, val_to_xs[val][:2]

    # k = 2
    for a1 in a_range:
        for a2 in a_range:
            if a1 != a2:
                target = P(a1) + P(a2)
                if target in val_to_xs:
                    for a3 in val_to_xs[target]:
                        if a3 != a1 and a3 != a2:
                            return True, 2, (a1, a2, a3)

    # k = 3
    if n >= 3:
        for a1 in a_range:
            for a2 in a_range:
                if a1 != a2:
                    for a3 in a_range:
                        if a3 != a1 and a3 != a2:
                            target = P(a1) + P(a2) + P(a3)
                            if target in val_to_xs:
                                for a4 in val_to_xs[target]:
                                    if a4 != a1 and a4 != a2 and a4 != a3:
                                        return True, 3, (a1, a2, a3, a4)
    return False, None, None

